import type { CategorySlug } from "./categories";

export type Spec = { label: string; value: string };

export type Product = {
  id: string;
  slug: string;
  name: string;
  brand: string;
  price: number;
  contribution: number;
  category: CategorySlug;
  subcategory: string;
  sku: string;
  inStock: boolean;
  imageQuery: string; // loremflickr keyword(s), comma-separated
  imageSeed: number; // deterministic seed
  description: string;
  highlights: string[];
  specs: Spec[];
};

// contribution = 60% of 25% of listed price (15% of price)
const c = (price: number, pct = 0.6 * 0.25) => Math.round(price * pct * 100) / 100;

// Studio product photos generated per product, keyed by slug.
const LOCAL_IMAGES = import.meta.glob<string>("../assets/products/*.jpg", {
  eager: true,
  query: "?url",
  import: "default",
});

const localImage = (slug: string): string | undefined =>
  LOCAL_IMAGES[`../assets/products/${slug}.jpg`];

export const productImage = (p: Product, size = 600, variant = 0) => {
  const local = localImage(p.slug);
  if (local) return local;
  const lock = p.imageSeed * 100 + variant;
  return `https://loremflickr.com/${size}/${size}/${encodeURIComponent(p.imageQuery)}?lock=${lock}`;
};


const sku = (id: string) => {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
  const hex = h.toString(16).toUpperCase().padStart(8, "0");
  return `FP-${hex.slice(0, 4)}-${hex.slice(4, 8)}-${id.toUpperCase()}`;
};

