/** Reorders a product list so pinned name-brand items lead, preserving pin order. */
export const applyPinned = (category: string, list: Product[]): Product[] => {
  const pins = PINNED_BY_CATEGORY[category];
  if (!pins) return list;
  const rank = new Map(pins.map((slug, i) => [slug, i]));
  const pinned = list
    .filter((p) => rank.has(p.slug))
    .sort((a, b) => rank.get(a.slug)! - rank.get(b.slug)!);
  const rest = list.filter((p) => !rank.has(p.slug));
  return [...pinned, ...rest];
};
